from pathlib import Path
import base64
import gzip
import hashlib
import json

ROOT = Path(__file__).resolve().parents[2]
OUT_DIR = ROOT / "workbenches/landscape-small-karst-field-r1"
OUT = OUT_DIR / "index.html"
BUILD = OUT_DIR / "build.json"

PAYLOAD = ""

raw = gzip.decompress(base64.b64decode(PAYLOAD))
sha = hashlib.sha256(raw).hexdigest()
expected = "ebaed7a1ae32c6c781aa2cbbbc35fd3d34fcec6e279bb72e0e3addd4db27116c"
if sha != expected:
    raise RuntimeError(f"payload sha mismatch: {sha}")

OUT_DIR.mkdir(parents=True, exist_ok=True)
OUT.write_bytes(raw)
build = {
    "schema": "LANDSCAPE_SMALL_KARST_CONTINUOUS_FIELD_R1",
    "date": "2026-09-19",
    "candidatePath": str(OUT.relative_to(ROOT)),
    "candidateSha256": sha,
    "candidateBytes": len(raw),
    "representation": "continuous signed-distance field raymarcher; no stored triangle mesh",
    "scaleIntent": "house-scale prototype first, scalable later",
    "sourceMethod": "Brick Mother V2.6-inspired domain warp, macro cavities, multi-band relief and independent mineral colour warp",
    "prototypeCount": 1,
    "controls": [
        "overall size",
        "height",
        "width",
        "macro deformation",
        "cavity depth",
        "domain warp",
        "detail strength",
        "detail scale",
        "colour warp",
        "top-soil eligibility",
    ],
    "preservedPreviousWorkbenches": True,
    "visualApproved": False,
    "productionReady": False,
}
BUILD.write_text(json.dumps(build, ensure_ascii=False, indent=2), encoding="utf-8")
print(json.dumps(build, ensure_ascii=False))
